contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint minSum, uint deposit) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (deposit)); require(deposit <= 1000000000000000000000000000000);
        require(deposit <= address(this).balance);

        // Fresh contract is uninitialized: configure MinSum.
        c.SetMinSum(minSum); if (__ESBMC_reverted()) return;

        // Fund the caller's recorded balance (also moves Ether into c).
        c.Deposit{value: deposit}(); if (__ESBMC_reverted()) return;

        uint balBefore = c.balances(address(this)); if (__ESBMC_reverted()) return;
        uint contractBalBefore = address(c).balance;

        // Collecting zero must be a harmless no-op when the threshold passes.
        bool reverted;
        c.Collect(0); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        assert(!reverted && c.balances(address(this)) == balBefore && address(c).balance == contractBalBefore);
    }

    receive() external payable {
        // Accept Ether so a zero-value low-level call in Collect succeeds.
    }
}

