// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {PRIVATE_ETH_CELL} from "../src/PRIVATE_ETH_CELL.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    PRIVATE_ETH_CELL c;

    function setUp() public {
        c = new PRIVATE_ETH_CELL();
    }

    function _run(uint256 minSum, uint256 deposit) internal {
        deposit = bound(deposit, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(deposit <= address(this).balance);
        try c.SetMinSum(minSum) {} catch { return; }
        try c.Deposit{value: deposit}() {} catch { return; }
        uint256 balBefore;
        try c.balances(address(this)) returns (uint256 __r) { balBefore = __r; } catch { return; }
        uint contractBalBefore = address(c).balance;
        bool reverted;
        try c.Collect(0) {
            reverted = false;
        } catch {
            reverted = true;
        }
        assertTrue(!reverted && c.balances(address(this)) == balBefore && address(c).balance == contractBalBefore);
    }

    function testFuzz_run(uint256 minSum, uint256 deposit) public {
        _run(minSum, deposit);
    }

    receive() external payable {
        // Accept Ether so a zero-value low-level call in Collect succeeds.
    }
}
